#include <bits/stdc++.h>
using namespace std;

static char ibuf[1 << 16];
static size_t ilen = 0, ipos = 0;

static inline int gc() {
    if (ipos == ilen) {
        ilen = fread(ibuf, 1, sizeof ibuf, stdin);
        ipos = 0;
        if (ilen == 0) return -1;
    }
    return ibuf[ipos++];
}

static long long readInt() {
    int c = gc();
    while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = gc();
    bool neg = c == '-';
    if (neg) c = gc();
    long long v = 0;
    while (c >= '0' && c <= '9') {
        v = v * 10 + (c - '0');
        c = gc();
    }
    return neg ? -v : v;
}

static string readToken() {
    int c = gc();
    while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = gc();
    string s;
    while (c > ' ') {
        s.push_back((char)c);
        c = gc();
    }
    return s;
}

int main() {
    string s = readToken();
    long long x = readInt(), y = readInt();
    // Make x <= y; then some optimal filling puts every unknown 0 before every unknown 1.
    if (x > y) {
        reverse(s.begin(), s.end());
        swap(x, y);
    }
    long long zero = 0, one = 0, cost = 0;
    for (char c : s) {
        if (c == '0') {
            cost += one * y;
            zero++;
        } else {
            cost += zero * x;
            one++;
        }
    }
    long long best = cost, left0 = 0, left1 = 0, right0 = zero, right1 = one;
    for (char c : s) {
        if (c == '0') {
            right0--;
            left0++;
        } else if (c == '1') {
            right1--;
            left1++;
        } else {
            // Flip this unknown from 1 to 0.
            right1--;
            cost += left1 * y + right1 * x - left0 * x - right0 * y;
            left0++;
            best = min(best, cost);
        }
    }
    printf("%lld\n", best % 1000000007LL);
}

import java.io.*;
import java.util.*;

public class Main {
    static final InputStream IN = System.in;
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int readByte() throws IOException {
        if (ptr == len) {
            len = IN.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = readByte();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = readByte();
        boolean neg = c == '-';
        if (neg) c = readByte();
        long v = 0;
        while (c >= '0' && c <= '9') {
            v = v * 10 + (c - '0');
            c = readByte();
        }
        return neg ? -v : v;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    static String next() throws IOException {
        int c = readByte();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = readByte();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') {
            sb.append((char) c);
            c = readByte();
        }
        return sb.toString();
    }

    public static void main(String[] args) throws IOException {
        String s = next();
        long x = nextLong(), y = nextLong();
        if (x > y) {
            s = new StringBuilder(s).reverse().toString();
            long t = x;
            x = y;
            y = t;
        }
