            if (s.charAt(i) == '0') {
                cost += one * y;
                zero++;
            } else {
                cost += zero * x;
                one++;
            }
        }
        long best = cost, left0 = 0, left1 = 0, right0 = zero, right1 = one;
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (c == '0') {
                right0--;
                left0++;
            } else if (c == '1') {
                right1--;
                left1++;
