package main

import (
	"fmt"
	"io"
	"os"
)

var data []byte
var pos int

// token returns the next whitespace-separated token of stdin.
func token() []byte {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return data[start:pos]
}

func nextInt() int {
	b := token()
	neg := len(b) > 0 && b[0] == '-'
	if neg {
		b = b[1:]
	}
	v := 0
	for _, c := range b {
		v = v*10 + int(c-'0')
	}
	if neg {
		return -v
	}
	return v
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	s := []byte(string(token()))
	x, y := nextInt(), nextInt()
	if x > y {
		for i, j := 0, len(s)-1; i < j; i, j = i+1, j-1 {
			s[i], s[j] = s[j], s[i]
		}
		x, y = y, x
	}
	zero, one, cost := 0, 0, 0
	for _, c := range s {
		if c == '0' {
			cost += one * y
			zero++
		} else {
			cost += zero * x
			one++
		}
	}
	best, left0, left1, right0, right1 := cost, 0, 0, zero, one
	for _, c := range s {
		switch c {
		case '0':
			right0--
			left0++
		case '1':
			right1--
			left1++
		default:
			right1--
			cost += left1*y + right1*x - left0*x - right0*y
			left0++
			best = min(best, cost)
		}
	}
	fmt.Println(best % 1000000007)
}
